let names:Map<string,string|null>|undefined;
function officialName(value:string):string|undefined {
  if(!names){names=new Map();for(const place of [...LANDMARKS,...SERVICE_STATIONS])if(place.nameEn){const previous=names.get(place.name);names.set(place.name,previous===undefined||previous===place.nameEn?place.nameEn:null);}for(const [name,english]of Object.entries(ROAD_NAMES_EN)){const previous=names.get(name);names.set(name,previous===undefined||previous===english?english:null);}}
  return names.get(value)||undefined;
}
function part(value:string):string {return translateEnglish(value)??officialName(value.trim())??value;}
