const escapeRegex=(value:string)=>value.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
function compile(source:string,target:string):[RegExp,(m:RegExpMatchArray)=>string] {
  const fields:number[]=[];let pattern='';let position=0;
  for(const token of source.matchAll(/\$\{(\d+)\}/g)){pattern+=escapeRegex(source.slice(position,token.index))+'([\\s\\S]*?)';fields.push(Number(token[1]));position=token.index!+token[0].length;}
  pattern+=escapeRegex(source.slice(position));
  const preserveName=source==='房主已轉交畀${0}。';
  return[new RegExp(`^${pattern}$`),matches=>target.replace(/\$\{(\d+)\}/g,(_token,index)=>{const capture=matches[fields.indexOf(Number(index))+1]||'';return preserveName&&Number(index)===0?capture:part(capture);}).replace(/(^|[^\d.])1 (trips|players)\b/g,(_match,prefix,word)=>`${prefix}1 ${word==='trips'?'trip':'player'}`)];
}
export const EN_PATTERNS:Array<[RegExp,(m:RegExpMatchArray)=>string]>=[
  [/^十二小時交更：(\d{2}:\d{2})(（翌日）)? · 未計加時$/u,m=>`12-hour handover: ${m[1]}${m[2]?' (next day)':''} · Excludes overtime`],
  ...[...templatePairs].sort((a,b)=>b[0].replace(/\$\{\d+\}/g,'').length-a[0].replace(/\$\{\d+\}/g,'').length).map(([source,target])=>compile(source,target)),
  [/^(.+?) · (.+?) → (.+)$/u,m=>`${part(m[1])} · ${part(m[2])} → ${part(m[3])}`],
  [/^(.+?) → (.+)$/u,m=>`${part(m[1])} → ${part(m[2])}`],
  [/^(.+?) · (左轉|右轉|直行|迴轉|靠左|靠右|中間)$/u,m=>`${part(m[1])} · ${part(m[2])}`],
  [/^港更 ([^\n]+) · 內部測試版$/u,m=>`Harbour Shift ${m[1]} · Internal test build`],
];
export function translateEnglish(source:string):string|undefined {
  if(Object.prototype.hasOwnProperty.call(EN_STRINGS,source))return EN_STRINGS[source];
  for(const [pattern,render]of EN_PATTERNS){const match=source.match(pattern);if(match)return render(match);}
  return /[\u3400-\u9fff]/u.test(source)?officialName(source.trim()):undefined;
}
